CREATE TABLE ontology_schema_version(version INTEGER PRIMARY KEY CHECK(version=1),files_root TEXT NOT NULL);
CREATE TABLE environments(env_num INTEGER PRIMARY KEY,env_key TEXT NOT NULL UNIQUE,body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE entity_types(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE attribute_definitions(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE entity_type_actions(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE entities(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE relationship_types(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE relationships(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE graph_aspects(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE structured_values(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE text_revisions(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE audit_events(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE catalog_entries(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE catalog_objects(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE TABLE catalog_state(env_num INTEGER NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(env_num,id));
CREATE UNIQUE INDEX entity_types_key ON entity_types(env_num,json_extract(body,'$.type_key'));
CREATE UNIQUE INDEX relationship_types_key ON relationship_types(env_num,json_extract(body,'$.type_key'));
CREATE UNIQUE INDEX graph_aspects_key ON graph_aspects(env_num,json_extract(body,'$.aspect_key'));
CREATE UNIQUE INDEX attribute_key ON attribute_definitions(env_num,json_extract(body,'$.entity_type_id'),json_extract(body,'$.attribute_key'));
CREATE INDEX entities_entity_type_id ON entities(env_num,json_extract(body,'$.entity_type_id'));
CREATE INDEX relationships_source_entity_id ON relationships(env_num,json_extract(body,'$.source_entity_id'));
CREATE INDEX relationships_target_entity_id ON relationships(env_num,json_extract(body,'$.target_entity_id'));
CREATE INDEX structured_values_entity_id ON structured_values(env_num,json_extract(body,'$.entity_id'));
CREATE INDEX text_revisions_entity_id ON text_revisions(env_num,json_extract(body,'$.entity_id'));
CREATE TABLE vectors(env_num INTEGER NOT NULL,attribute_id TEXT NOT NULL,entity_id TEXT NOT NULL,vector_id TEXT NOT NULL,revision INTEGER NOT NULL,is_deleted INTEGER NOT NULL,emb BLOB NOT NULL,PRIMARY KEY(env_num,attribute_id,entity_id),UNIQUE(env_num,vector_id));
